 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            colors = {grid[y][x] for y, x in cells}
            if r1 - r0 == 2 and c1 - c0 == 2 and len(colors) == 3:
                candidates.append([row[c0:c1 + 1] for row in grid[r0:r1 + 1]])
    if len(candidates) != 1:
        raise ValueError(f"Expected one 3x3 three-color object, got {len(candidates)}")
    return candidates[0]


